begin;
do $$
declare admin uuid:=gen_random_uuid();clerk uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();sid bigint;pid bigint;lesson uuid;r jsonb;n int;v bigint;
begin
 insert into public.submission_cohorts(name) values('10月班'),('11月班') on conflict do nothing;
 insert into auth.users(id,email,email_confirmed_at) values(admin,'review-admin@example.invalid',now()),(clerk,'review-clerk@example.invalid',now()),(outsider,'review-finance@example.invalid',now());
 insert into public.user_roles(user_id,role) values(admin,'super_admin'),(outsider,'finance');
 insert into amas_private.attendance_operators(user_id,granted_by) values(clerk,admin);
 insert into public.submissions(type,name,cohort) values('application','历史姓名','10月班') returning id into sid;
 insert into public.submissions(type,name,cohort) values('application','漏登同学','10月班') returning id into pid;
 perform set_config('amas.test.uid',clerk::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',clerk,'aal','aal2')::text,true);
 execute 'set local role authenticated';
 r:=public.attendance_save('2026-10-05',null,0,'合成课次',jsonb_build_array(jsonb_build_object('id',sid,'status','excused','note','已提前通知')));if not (r->>'ok')::boolean then raise exception 'R01 save %',r;end if;lesson:=(r->>'session')::uuid;v:=(r->>'version')::bigint;
 begin perform public.admin_attendance_month('10月班','2026-10-01');raise exception 'R02 clerk report allowed';exception when insufficient_privilege then null;end;
 begin perform public.admin_attendance_history('10月班','2026-10-01');raise exception 'R03 clerk history allowed';exception when insufficient_privilege then null;end;
 execute 'reset role';
 if not (select attendance_roster_frozen from public.cohort_sessions where id=lesson) then raise exception 'R04 new roster not frozen';end if;
 update public.submissions set cohort='11月班',name='改名以后' where id=sid;
 perform set_config('amas.test.uid',admin::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',admin,'aal','aal2')::text,true);
 execute 'set local role authenticated';r:=public.admin_attendance_month('10月班','2026-10-15');
 if r->>'month'<>'2026-10-01' or r#>>'{sessions,0,expected}'<>'2' or r#>>'{sessions,0,unmarked}'<>'1' or not exists(select 1 from jsonb_array_elements(r->'students') x where x->>'name'='历史姓名' and x->>'excused'='1') then raise exception 'R05 snapshot/month/unmarked wrong %',r;end if;
 if public.admin_attendance_month('10月班','2026-11-01')->'sessions'<>'[]'::jsonb then raise exception 'R06 empty month wrong';end if;
 r:=public.admin_attendance_history('10月班','2026-10-01');if jsonb_array_length(r->'rows')<>1 or r#>>'{rows,0,new_status}'<>'excused' or r#>>'{rows,0,new_note}'<>'已提前通知' or r#>'{rows,0}' ? 'actor_id' then raise exception 'R07 whitelisted history wrong %',r;end if;
 execute 'reset role';
 select count(*) into n from amas_private.attendance_changes;
 update public.cohort_marks set homework='done' where session_id=lesson;
 if (select count(*) from amas_private.attendance_changes)<>n then raise exception 'R08 homework-only change polluted history';end if;
 perform set_config('amas.test.uid',clerk::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',clerk,'aal','aal2')::text,true);
 execute 'set local role authenticated';r:=public.attendance_day('2026-10-05');if r::text not like '%历史姓名%' or r::text like '%改名以后%' then raise exception 'R09 historical clerk roster changed %',r;end if;
 execute 'reset role';select attendance_version into v from public.cohort_sessions where id=lesson;execute 'set local role authenticated';
 r:=public.attendance_save('2026-10-05',lesson,v,'',jsonb_build_array(jsonb_build_object('id',sid,'status','excused','note','已提前通知')));if r->>'ok'<>'true' then raise exception 'R10 historical correction rejected %',r;end if;
 execute 'reset role';if (select count(*) from amas_private.attendance_changes)<>n then raise exception 'R11 no-op duplicated history';end if;
 -- Staff changes and row deletion remain visible, and a deletion counts as unmarked.
 update public.cohort_marks set attendance='late',attendance_note='核对后更正' where session_id=lesson and submission_id=sid;
 delete from public.cohort_marks where session_id=lesson and submission_id=sid;
 perform set_config('amas.test.uid',admin::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',admin,'aal','aal2')::text,true);
 execute 'set local role authenticated';r:=public.admin_attendance_month('10月班','2026-10-01');if r#>>'{sessions,0,unmarked}'<>'2' then raise exception 'R12 deleted mark disappeared from denominator';end if;execute 'reset role';
 insert into amas_private.attendance_changes(actor_name,cohort,held_on,session_id,title,operation) select '测试维护','10月班','2026-10-05',lesson,'分页','session_changed' from generate_series(1,52);
 execute 'set local role authenticated';r:=public.admin_attendance_history('10月班','2026-10-01');if jsonb_array_length(r->'rows')<>50 or r->>'next_before' is null then raise exception 'R13 history pagination missing';end if;
 r:=public.admin_attendance_history('10月班','2026-10-01',(r->>'next_before')::bigint);if jsonb_array_length(r->'rows')<>5 or r->>'next_before' is not null then raise exception 'R14 history pagination overlaps %',r;end if;execute 'reset role';
 delete from public.cohort_sessions where id=lesson;
 if not exists(select 1 from amas_private.attendance_changes where session_id=lesson and operation='session_deleted') or not exists(select 1 from amas_private.attendance_changes where session_id=lesson and operation='delete') then raise exception 'R15 deletion erased history';end if;
 perform set_config('amas.test.uid',outsider::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'aal','aal2')::text,true);
 execute 'set local role authenticated';begin perform public.admin_attendance_month('10月班','2026-10-01');raise exception 'R16 finance report allowed';exception when insufficient_privilege then null;end;
 begin perform public.admin_attendance_history('10月班','2026-10-01');raise exception 'R17 finance history allowed';exception when insufficient_privilege then null;end;
 begin select count(*) into n from amas_private.attendance_changes;raise exception 'R18 private raw ledger readable';exception when insufficient_privilege then null;end;execute 'reset role';
 perform set_config('amas.test.uid',admin::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',admin,'aal','aal1')::text,true);
 update public.portal_settings set value='true'::jsonb where key='mfa_required';execute 'set local role authenticated';begin perform public.admin_attendance_month('10月班','2026-10-01');raise exception 'R19 MFA bypass';exception when insufficient_privilege then null;end;execute 'reset role';
 execute 'set local role anon';begin perform public.admin_attendance_month('10月班','2026-10-01');raise exception 'R20 anon access';exception when insufficient_privilege then null;end;execute 'reset role';
 raise notice 'PASS R01-R20 reports, frozen roster, no-op audit, staff/deletion history, pagination, clerk/finance/anon/MFA denial';
end $$;
rollback;
